package org.brightstats.stats;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
public final class PolynomialScoreChecks {
    private static int checks;
    private static void require(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    private static void archive(JsonObject item,boolean component)throws Exception{var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();String key=component?"componentPolynomial":"observedPolynomial";var project=new JsonObject();project.addProperty("formatVersion",1);project.add("observations",item.get("observations"));JsonArray names=new JsonArray();for(int i=0;i<item.getAsJsonArray("observations").get(0).getAsJsonArray().size();i++)names.add("V"+i);project.add("columnNames",names);project.add("blocks",new JsonArray());project.add("edges",new JsonArray());var numeric=new JsonObject();numeric.add(key,item.get("point"));if(item.has("bootstrap"))numeric.add("bootstrap",item.get("bootstrap"));var report=org.brightstats.report.ReportArchive.create(component?"COMPONENT_POLYNOMIAL":"OBSERVED_POLYNOMIAL",project,numeric,new JsonArray(),List.of());var decoded=JsonParser.parseString(new Gson().toJson(report)).getAsJsonObject();org.brightstats.report.ReportArchive.validate(decoded);Object restored=component?org.brightstats.report.PolynomialReports.component(decoded):org.brightstats.report.PolynomialReports.observed(decoded);var replay=new JsonObject();replay.add(key,gson.toJsonTree(restored));if(item.has("bootstrap"))replay.add("bootstrap",gson.toJsonTree(org.brightstats.report.PolynomialReports.bootstrap(decoded)));var again=org.brightstats.report.ReportArchive.create("CHECK",project,replay,new JsonArray(),List.of());require(report.get("results").equals(again.get("results")),"Numeric archive preserves undefined values and full options");}
    public static void main(String[] args)throws Exception{
        Random random=new Random(517);int n=66;double[][] data=new double[n][5],measurement=new double[n][9];for(int i=0;i<n;i++){double x=2+random.nextGaussian(),w=-1+.8*random.nextGaussian(),control=random.nextGaussian(),m=.4*x+.2*w+.3*x*w+.25*control+.25*random.nextGaussian(),y=.5*m+.6*x+.25*x*x-.2*x*w+.15*x*x*w+.3*control+.25*random.nextGaussian();data[i]=new double[]{x,w,m,y,control};double[] components={x,w,y};for(int k=0;k<3;k++)for(int j=0;j<3;j++)measurement[i][3*k+j]=components[k]+.15*random.nextGaussian();}
        var paths=List.of(new PlsSem.Edge(0,2),new PlsSem.Edge(1,2),new PlsSem.Edge(2,3),new PlsSem.Edge(0,3),new PlsSem.Edge(1,3));var extensions=List.of(new NonlinearPls.Extension(2,new int[]{0,1}),new NonlinearPls.Extension(3,new int[]{0,0}),new NonlinearPls.Extension(3,new int[]{0,1}),new NonlinearPls.Extension(3,new int[]{0,0,1}));var model=new ObservedPolynomial.Model(List.of("X","W","M","Y","Control"),new int[]{0,1,2,3,4},paths,extensions,0,3,new int[]{4});var specification=new NonlinearPls.Specification(extensions,List.of(new PathProcess.Probe("W=-1",Map.of(0,2.,1,-1.)),new PathProcess.Probe("W=0",Map.of(0,2.,1,0.))),new NonlinearPls.Grid(0,3,.5,3.5,7));var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonArray observed=new JsonArray(),components=new JsonArray();List<NonlinearPls.Effect> rawReference=null;
        for(var metric:PathProcess.Metric.values())for(var covariance:List.of(RobustRegression.Covariance.CLASSICAL,RobustRegression.Covariance.HC3)){var options=new PathProcess.Options(metric,covariance,.95,true);var fit=ObservedPolynomial.fit(data,model,options,specification);require(fit.polynomial().equations().size()==2&&fit.equations().size()==2,"Both observed equations fitted");require(fit.polynomial().equations().getFirst().regressors().stream().anyMatch(term->Arrays.equals(term.factors(),new int[]{4})),"Control included");if(rawReference==null)rawReference=fit.rawEffects();else for(int i=0;i<rawReference.size();i++)require(Math.abs(rawReference.get(i).value()-fit.rawEffects().get(i).value())<2e-10,"Raw local derivatives invariant to centering/scaling");JsonObject item=new JsonObject();item.add("observations",gson.toJsonTree(data));item.add("model",gson.toJsonTree(model));item.add("options",gson.toJsonTree(options));item.add("specification",gson.toJsonTree(specification));item.add("point",gson.toJsonTree(fit));if(covariance==RobustRegression.Covariance.HC3){var bootOptions=new Bootstrap.Options(40,284,.95,metric==PathProcess.Metric.STANDARDIZED?BootstrapIntervals.Method.BCA:BootstrapIntervals.Method.PERCENTILE,RegressionBootstrap.Convention.STANDARD,true);var boot=ObservedPolynomial.bootstrap(data,model,options,specification,bootOptions,null);require(boot.inference().successful()==40,"Observed bootstrap");item.add("bootstrap",gson.toJsonTree(boot.inference()));}archive(item,false);observed.add(item);}
        var noControls=ObservedPolynomial.fit(data,model,new PathProcess.Options(PathProcess.Metric.UNSTANDARDIZED,RobustRegression.Covariance.HC3,.95,false),specification);require(noControls.polynomial().equations().stream().flatMap(eq->eq.regressors().stream()).noneMatch(term->Arrays.stream(term.factors()).anyMatch(i->i==4)),"Controls can be disabled");
        var names=java.util.stream.IntStream.range(0,9).mapToObj(i->"V"+i).toList();var blocks=List.of(new PlsSem.Block("X",new int[]{0,1,2},PlsSem.Mode.A),new PlsSem.Block("W",new int[]{3,4,5},PlsSem.Mode.A),new PlsSem.Block("Y",new int[]{6,7,8},PlsSem.Mode.A));var structural=List.of(new PlsSem.Edge(0,2),new PlsSem.Edge(1,2));var nonlinear=new NonlinearPls.Specification(List.of(new NonlinearPls.Extension(2,new int[]{0,0}),new NonlinearPls.Extension(2,new int[]{0,1})),List.of(new PathProcess.Probe("Mean",Map.of()),new PathProcess.Probe("W=1",Map.of(1,1.))),new NonlinearPls.Grid(0,2,-1,1,5));var generalized=Gsca.fromBlocks(names,blocks,structural);for(var estimator:ComponentScores.Estimator.values()){var componentModel=estimator==ComponentScores.Estimator.PLS?ComponentScores.Model.pls(blocks,structural,PlsSem.Options.defaults()):ComponentScores.Model.gsca(generalized.model(),Gsca.Options.defaults(),generalized.columns());var fit=ComponentPolynomial.fit(measurement,componentModel,nonlinear);require(fit.firstStage().model().estimator()==estimator,"Actual first-stage estimator");require(fit.polynomial().equations().getFirst().regressors().size()==4,"Component hierarchy");var bootstrap=new Bootstrap.Options(40,716,.95,BootstrapIntervals.Method.PERCENTILE,RegressionBootstrap.Convention.STANDARD,true);var boot=ComponentPolynomial.bootstrap(measurement,componentModel,nonlinear,bootstrap,null);require(boot.inference().successful()==40,"Complete component bootstrap");JsonObject item=new JsonObject();item.add("observations",gson.toJsonTree(measurement));item.add("model",gson.toJsonTree(componentModel));item.add("specification",gson.toJsonTree(nonlinear));item.add("point",gson.toJsonTree(fit));item.add("bootstrap",gson.toJsonTree(boot.inference()));archive(item,true);components.add(item);}
        Thread.currentThread().interrupt();try{ObservedPolynomial.fit(data,model,PathProcess.Options.defaults(),specification);throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}Path out=Path.of(args[0]);Files.createDirectories(out);Files.writeString(out.resolve("observed.json"),gson.toJson(observed));Files.writeString(out.resolve("components.json"),gson.toJson(components));System.out.println("{\"checks\":"+checks+",\"observed_cases\":"+observed.size()+",\"component_cases\":"+components.size()+"}");
    }
}
